14	function loadTexture(
15	  loader: THREE.TextureLoader,
16	  url: string,
17	): Promise<THREE.Texture | null> {
18	  return new Promise((resolve) => {
19	    loader.load(url, resolve, undefined, () => resolve(null));
20	  });
21	}
