23	export class AboutProofRenderer {
24	  private _renderer: THREE.WebGLRenderer | null = null;
25	  private _scene: THREE.Scene | null = null;
26	  private _camera: THREE.PerspectiveCamera | null = null;
27	  private _group: THREE.Group | null = null;
28	  private _geometries: THREE.BufferGeometry[] = [];
29	  private _materials: THREE.Material[] = [];
30	  private _textures: THREE.Texture[] = [];
31	  private _rafId: number | null = null;
32	  private _resizeObserver: ResizeObserver | null = null;
33	  private _intersectionObserver: IntersectionObserver | null = null;
34	  private _rendering = false;
35	  private _disposed = false;
36	  private _canvas: HTMLCanvasElement | null = null;
37	
38	  async init(canvas: HTMLCanvasElement): Promise<void> {
39	    this._canvas = canvas;
40	
41	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
42	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
43	    renderer.setClearAlpha(0);
44	    this._renderer = renderer;
45	
46	    const scene = new THREE.Scene();
47	    this._scene = scene;
48	
49	    const w = Math.max(canvas.clientWidth, 1);
50	    const h = Math.max(canvas.clientHeight, 1);
51	    const camera = new THREE.PerspectiveCamera(50, w / h, 0.1, 1000);
52	    camera.position.set(-10, 1.5, 10);
53	    camera.lookAt(0, 0, 0);
54	    this._camera = camera;
55	
56	    scene.add(new THREE.AmbientLight(0xffffff, 0.9));
57	
58	    const group = new THREE.Group();
59	    this._group = group;
60	    scene.add(group);
61	
62	    let imageUrls: string[] = [];
63	    try {
64	      const response = await fetchWorksList(0, MAX_IMAGES, null);
65	      imageUrls = response.items
66	        .filter((item: WorkApiItem) => item.thumbnailImage.length > 0)
67	        .map((item: WorkApiItem) => item.thumbnailImage)
68	        .slice(0, MAX_IMAGES);
69	    } catch {
70	      // ignore — fallback to colored cards
71	    }
72	
73	    if (this._disposed) return;
74	
75	    if (imageUrls.length > 0) {
76	      const loader = new THREE.TextureLoader();
77	      const textures = await Promise.all(imageUrls.map((url) => loadTexture(loader, url)));
78	      if (this._disposed) return;
79	
80	      textures.forEach((texture, i) => {
81	        if (texture) this._textures.push(texture);
82	        this._addCard(group, i, textures.length, texture);
83	      });
84	    } else {
85	      for (let i = 0; i < FALLBACK_COUNT; i++) {
86	        this._addCard(group, i, FALLBACK_COUNT, null);
87	      }
88	    }
89	
90	    this._syncSize();
91	    this._observeResize();
92	    this._observeVisibility();
93	  }
94	
95	  dispose(): void {
96	    this._disposed = true;
97	    this._stopRaf();
98	
99	    this._resizeObserver?.disconnect();
100	    this._resizeObserver = null;
101	
102	    this._intersectionObserver?.disconnect();
103	    this._intersectionObserver = null;
104	
105	    this._geometries.forEach((g) => g.dispose());
106	    this._geometries = [];
107	
108	    this._materials.forEach((m) => m.dispose());
109	    this._materials = [];
110	
111	    this._textures.forEach((t) => t.dispose());
112	    this._textures = [];
113	
114	    this._renderer?.dispose();
115	    this._renderer?.forceContextLoss();
116	    this._renderer = null;
117	    this._scene = null;
118	    this._camera = null;
119	    this._group = null;
120	    this._canvas = null;
121	  }
122	
123	  private _addCard(
124	    group: THREE.Group,
125	    index: number,
126	    total: number,
127	    texture: THREE.Texture | null,
128	  ): void {
129	    const angle = (index / total) * Math.PI * 2;
130	    const x = SPHERE_RADIUS * Math.cos(angle);
131	    const z = SPHERE_RADIUS * Math.sin(angle);
132	
133	    const geo = new THREE.PlaneGeometry(IMAGE_SIZE, IMAGE_SIZE);
134	    this._geometries.push(geo);
135	
136	    const mat = new THREE.MeshBasicMaterial({
137	      map: texture ?? null,
138	      color: texture ? 0xffffff : FALLBACK_COLORS[index % FALLBACK_COLORS.length],
139	      side: THREE.DoubleSide,
140	    });
141	    this._materials.push(mat);
142	
143	    const mesh = new THREE.Mesh(geo, mat);
144	    mesh.position.set(x, 0, z);
145	    mesh.lookAt(0, 0, 0);
146	    group.add(mesh);
147	  }
148	
149	  private readonly _tick = (): void => {
150	    if (this._disposed || !this._rendering) return;
151	    if (this._group) this._group.rotation.y += ROTATION_SPEED_Y;
152	    if (this._renderer && this._scene && this._camera) {
153	      this._renderer.render(this._scene, this._camera);
154	    }
155	    this._rafId = requestAnimationFrame(this._tick);
156	  };
157	
158	  private _startRaf(): void {
159	    if (this._rafId !== null || this._disposed) return;
160	    this._rendering = true;
161	    this._rafId = requestAnimationFrame(this._tick);
162	  }
163	
164	  private _stopRaf(): void {
165	    this._rendering = false;
166	    if (this._rafId !== null) {
167	      cancelAnimationFrame(this._rafId);
168	      this._rafId = null;
169	    }
170	  }
171	
172	  private _syncSize(): void {
173	    const canvas = this._canvas;
174	    const renderer = this._renderer;
175	    const camera = this._camera;
176	    if (!canvas || !renderer || !camera) return;
177	    const w = canvas.clientWidth;
178	    const h = canvas.clientHeight;
179	    if (w <= 0 || h <= 0) return;
180	    renderer.setSize(w, h, false);
181	    camera.aspect = w / h;
182	    camera.updateProjectionMatrix();
183	  }
184	
185	  private _observeResize(): void {
186	    if (!this._canvas) return;
187	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
188	    this._resizeObserver.observe(this._canvas);
189	  }
190	
191	  private _observeVisibility(): void {
192	    if (!this._canvas) return;
193	    this._intersectionObserver = new IntersectionObserver(
194	      (entries) => {
195	        if (entries[0]?.isIntersecting) {
196	          this._startRaf();
197	        } else {
198	          this._stopRaf();
199	        }
200	      },
201	      { threshold: 0 },
202	    );
203	    this._intersectionObserver.observe(this._canvas);
204	  }
205	}
