9	export class AboutPageRuntime implements IPageRuntime {
10	  private _appManager: AppManager | null = null;
11	  private _proofRenderer: AboutProofRenderer | null = null;
12	
13	  async init(root?: ParentNode | null): Promise<void> {
14	    const three = aboutConfig.three;
15	    if (three) {
16	      const env = EnvSetup.shouldInit({
17	        canvasId: three.canvasId,
18	        root,
19	        allowedPageTypes: new Set(["about"]),
20	      });
21	      if (env.shouldInit) {
22	        this._appManager?.dispose();
23	        this._appManager = new AppManager();
24	        await this._appManager.run(aboutConfig, root);
25	      }
26	    }
27	
28	    const canvas = (root ?? document).querySelector<HTMLCanvasElement>(
29	      `#${PROOF_CANVAS_ID}`,
30	    );
31	    if (canvas instanceof HTMLCanvasElement) {
32	      this._proofRenderer?.dispose();
33	      this._proofRenderer = new AboutProofRenderer();
34	      await this._proofRenderer.init(canvas);
35	    }
36	  }
37	
38	  dispose(): void {
39	    this._appManager?.dispose();
40	    this._appManager = null;
41	    this._proofRenderer?.dispose();
42	    this._proofRenderer = null;
43	  }
44	}
